Pseudocode:
```js
var hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');
var amazon = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017').filter(ee.Filter.eq('country_co', 'BR'));
var lossYear = hansen.select('lossyear').clip(amazon);
// Years coded 20-24 for 2020-2024
var loss2020 = lossYear.eq(20).multiply(ee.Image.pixelArea());
var area = loss2020.reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: amazon,
  scale: 30,
  maxPixels: 1e13
});
```
Get hectares per year by dividing by 10⁴. Earth Engine handles parallelization across petabytes.
